in-degree.pseudocode:
def in_degrees(adj):
    indeg = {v: 0 for v in adj}
    for u in adj:
        for v in adj[u]:
            indeg[v] += 1  # 간선 u→v 마다 v 증가
    # 진입 차수 0 = 선행 제약 없는 시작 정점
    sources = [v for v in adj if indeg[v] == 0]
    return indeg, sources

in-place-algorithm.pseudocode:
def reverse_in_place(a):
    i, j = 0, len(a) - 1
    while i < j:
        # 보조 배열 없이 양 끝 원소 교환
        a[i], a[j] = a[j], a[i]
        i += 1
        j -= 1
    return a  # 추가 공간 O(1)

indirect-block.pseudocode:
LEVELS = ['single', 'double', 'triple']

def locate(n, ptrs=1024, direct=12):
    # 논리 블록 번호 n → (단계, 단계별 인덱스)
    if n < direct:
        return ('direct', [n])  # 추가 디스크 접근 없음
    n -= direct
    for level, name in enumerate(LEVELS, 1):
        span = ptrs ** level  # 이 단계가 덮는 블록 수
        if n < span:
            idx = []
            for k in range(level - 1, -1, -1):
                idx.append(n // ptrs ** k % ptrs)
            return (name, idx)  # 간접 블록 level회 추가 읽기
        n -= span
    raise ValueError('최대 파일 크기 초과')

inductive-miner.pseudocode:
def inductive_miner(log):
    acts = activities(log)
    if len(acts) == 1:  # 기본 사례 (빈 트레이스 처리 생략)
        return Leaf(acts.pop())
    dfg = directly_follows_graph(log)
    # 시도 순서: 배타선택 → 순차 → 병렬 → 루프
    for op in ('xor', 'seq', 'par', 'loop'):
        parts = find_cut(dfg, op)  # 활동 집합 분할
        if parts:
            sublogs = split_log(log, parts, op)
            children = [inductive_miner(s) for s in sublogs]
            return Node(op, children)  # 재귀 결과 결합
    return flower_model(acts)  # 분할 불가: fall-through

