information-entropy.pseudocode:
def entropy(probs):
    h = 0.0
    for p in probs:
        if p > 0:  # 0·log0 = 0으로 정의
            h -= p * log2(p)
    return h  # 단위: 비트/기호

def entropy_of(data):  # 관측 데이터의 경험적 엔트로피
    counts = {}
    for s in data:
        counts[s] = counts.get(s, 0) + 1
    n = len(data)
    return entropy([c / n for c in counts.values()])

