interleaving.pseudocode:
def interleavings(a, b):
    # a, b: 각 실행 흐름의 원자적 명령 순서(내부 순서 유지)
    if not a:
        return [b[:]]
    if not b:
        return [a[:]]
    first_a = [[a[0]] + r for r in interleavings(a[1:], b)]
    first_b = [[b[0]] + r for r in interleavings(a, b[1:])]
    return first_a + first_b  # 개수 = (n+m)!/(n!m!)

internal-rate-of-return.pseudocode:
def npv(rate, cashflows):
    return sum(c / (1 + rate) ** t
               for t, c in enumerate(cashflows))

def irr(cashflows, lo=-0.99, hi=1.0, tol=1e-7):
    # 이분법: 양 끝 NPV 부호가 달라야 해 존재
    if npv(lo, cashflows) * npv(hi, cashflows) > 0:
        return None  # 구간 내 해 없음
    while hi - lo > tol:
        mid = (lo + hi) / 2
        if npv(lo, cashflows) * npv(mid, cashflows) <= 0:
            hi = mid  # 해가 [lo, mid]에 있음
        else:
            lo = mid
    return (lo + hi) / 2

