interpreter-pattern.pseudocode:
class Num:  # 터미널 표현식
    def __init__(self, v):
        self.v = v
    def interpret(self, ctx):
        return self.v

class Var:  # 터미널 표현식
    def __init__(self, name):
        self.name = name
    def interpret(self, ctx):
        return ctx[self.name]

class Add:  # 논터미널: 하위 식을 재귀 해석
    def __init__(self, left, right):
        self.left, self.right = left, right
    def interpret(self, ctx):
        l = self.left.interpret(ctx)
        return l + self.right.interpret(ctx)

expr = Add(Var('x'), Num(3))  # 구문 트리: x + 3
print(expr.interpret({'x': 5}))  # 8

introsort.pseudocode:
def introsort(a):
    if len(a) > 1:
        depth = 2 * floor(log2(len(a)))  # 재귀 깊이 한계
        intro(a, 0, len(a) - 1, depth)

def intro(a, lo, hi, depth):
    if hi - lo + 1 <= 16:
        insertion_sort(a, lo, hi)  # 소구간
        return
    if depth == 0:
        heap_sort(a, lo, hi)  # 퀵 퇴화 → 힙 정렬 전환
        return
    p = partition(a, lo, hi)  # 퀵 정렬 분할
    intro(a, lo, p - 1, depth - 1)
    intro(a, p + 1, hi, depth - 1)

inverted-index.pseudocode:
def build_index(docs):  # docs: {문서ID: 텍스트}
    index = {}  # 단어 → {문서ID: [출현 위치]}
    for doc_id in sorted(docs):
        for pos, term in enumerate(tokenize(docs[doc_id])):
            postings = index.setdefault(term, {})
            postings.setdefault(doc_id, []).append(pos)
    return index

def intersect(p1, p2):  # 정렬된 게시 목록 AND (병합)
    i = j = 0
    out = []
    while i < len(p1) and j < len(p2):
        if p1[i] == p2[j]:
            out.append(p1[i])
            i += 1
            j += 1
        elif p1[i] < p2[j]:
            i += 1
        else:
            j += 1
    return out  # O(len(p1) + len(p2))

inverted-page-table.pseudocode:
def translate(pid, vaddr, ipt, anchor, page_size):
    p, d = divmod(vaddr, page_size)
    # 해시 앵커 테이블 → 해당 체인의 첫 프레임
    i = anchor[hash((pid, p)) % len(anchor)]
    while i is not None:
        entry = ipt[i]  # 프레임 i를 소유한 (pid, page)
        if entry.pid == pid and entry.page == p:
            return i * page_size + d  # 인덱스 = 프레임 번호
        i = entry.next  # 해시 충돌 체인 따라가기
    raise PageFault(pid, p)
